// One-off importer: turns the compiled icons of @signozhq/icons (MIT) into
// source files under src/ds/icons/svg. Kept for re-running against a newer
// release; the generated files are ours from then on.
// Usage: node scripts/import-signoz-icons.mjs <path-to-unpacked-package>
import fs from 'node:fs';
import path from 'node:path';

const pkg = process.argv[2];
if (!pkg) throw new Error('usage: import-signoz-icons.mjs <unpacked @signozhq/icons dir>');
const srcDir = path.join(pkg, 'dist/lib/icons');
const outDir = path.resolve('src/ds/icons/svg');
fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

const files = fs.readdirSync(srcDir).filter((f) => f.endsWith('.js') && f !== 'index.js');
for (const file of files) {
	const name = file.replace(/\.js$/, '');
	const code = fs.readFileSync(path.join(srcDir, file), 'utf8');
	// Minified names differ per file: grab the rest-props binding and the svg element.
	const m = code.match(/\.\.\.(\w+) \}, \w+\) => \{\n\tlet (\w+) = ([\s\S]*?), \w+ = \2\.props\.viewBox/);
	if (!m) throw new Error(`unexpected shape: ${file}`);
	const [, rest, , body] = m;
	const svg = body.replace(/\/\* @__PURE__ \*\/ /g, '').replace(/^\t/gm, '');
	const runtime = /\bjsxs\(/.test(svg) ? 'jsx, jsxs' : 'jsx';
	fs.writeFileSync(
		path.join(outDir, `${name}.ts`),
		`import { ${runtime} } from 'react/jsx-runtime';\nimport { createIcon } from '../create-icon';\n\nexport default /* @__PURE__ */ createIcon('${name}', (${rest}) =>\n\t${svg},\n);\n`,
	);
}

// Barrel: the published index also exports aliases (several names per file).
const index = fs.readFileSync(path.join(srcDir, 'index.js'), 'utf8');
const imports = new Map(
	[...index.matchAll(/import (\w+) from "\.\/(\w+)\.js";/g)].map((m) => [m[1], m[2]]),
);
const exported = index.match(/export \{([^}]*)\}/)[1].split(',').map((s) => s.trim()).filter(Boolean);
const lines = exported.map((e) => {
	const [local, alias] = e.split(/\s+as\s+/);
	return `export { default as ${alias ?? local} } from './svg/${imports.get(local)}';`;
});
fs.writeFileSync(
	path.resolve('src/ds/icons/index.ts'),
	`// Generated by scripts/import-signoz-icons.mjs.\nexport { createIcon, type IconProps } from './create-icon';\nexport { ICON_SIZE_MAP, STROKE_WIDTH_MAP, type IconSize, type IconStrokeWidth } from './icon-config';\n${lines.join('\n')}\n`,
);
console.log(`${files.length} icons, ${exported.length} exports`);
